public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine().trim());
        int[] x = new int[N];
        int[] y = new int[N];
        for (int i = 0; i < N; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            x[i] = Integer.parseInt(st.nextToken());
            y[i] = Integer.parseInt(st.nextToken());
        }

        int M = N * (N - 1) / 2 + N;
        long[] edges = new long[M];
        int idx = 0;

        // Source edges: from palace (index N) to each tent
        for (int v = 0; v < N; v++) {
            int d = x[v] * x[v] + y[v] * y[v];
            edges[idx++] = ((long) d << 22) | ((long) N << 11) | v;
        }

        // Undirected edges between tents
        for (int u = 0; u < N; u++) {
            int xu = x[u], yu = y[u];
            for (int v = u + 1; v < N; v++) {
                int dx = xu - x[v];
                int dy = yu - y[v];
                int d = dx * dx + dy * dy;
                edges[idx++] = ((long) d << 22) | ((long) u << 11) | v;
            }
        }

        Arrays.sort(edges);

        int[] best = new int[N + 1];
        Arrays.fill(best, -1);
        best[N] = 0;

        int[] temp = new int[N];
        Arrays.fill(temp, -1);
        int[] touched = new int[N];

        int i = M - 1;
        while (i >= 0) {
            long key = edges[i];
            int d = (int) (key >>> 22);
            int j = i;
            while (j >= 0 && ((edges[j] >>> 22) == d)) {
                j--;
            }

            int touchCount = 0;
            for (int k = j + 1; k <= i; k++) {
                long e = edges[k];
                int u = (int) ((e >>> 11) & 2047);
                int v = (int) (e & 2047);

                if (u == N) {
                    // Source edge
                    if (best[N] >= 0) {
                        int cand = best[N] + 1;
                        if (cand > temp[v]) {
                            if (temp[v] == -1) {
                                touched[touchCount++] = v;
                            }
                            temp[v] = cand;
                        }
                    }
                } else {
                    // Undirected edge u < v
                    if (best[u] >= 0) {
                        int cand = best[u] + 1;
                        if (cand > temp[v]) {
                            if (temp[v] == -1) {
                                touched[touchCount++] = v;
                            }
                            temp[v] = cand;
                        }
                    }
                    if (best[v] >= 0) {
                        int cand = best[v] + 1;
                        if (cand > temp[u]) {
                            if (temp[u] == -1) {
                                touched[touchCount++] = u;
                            }
                            temp[u] = cand;
                        }
                    }
                }
            }

            for (int t = 0; t < touchCount; t++) {
                int v = touched[t];
                if (temp[v] > best[v]) {
                    best[v] = temp[v];
                }
                temp[v] = -1;
            }

            i = j;
        }

        int ans = 0;
        for (int v = 0; v < N; v++) {
            if (best[v] > ans) {
                ans = best[v];
            }
        }
        System.out.println(ans);
    }
}
